// access-contract — TPL-01, STK-46, API-01 (INV-T-4934).
//
// Server interfaces and DTOs generated by platform-build's gst.contract-server from access's OpenAPI document in the
// pinned platform-contracts bundle (`stageContracts()` lays it out as a build-local Maven repository, as
// product-runtime does). Never hand-edited; no logic lives here.

plugins {
    id("gst.contract-server")
}

// ---- the pinned platform-contracts bundle as a build-local Maven layout ----

val contractsBundle =
    configurations.create("contractsBundle") {
        isCanBeConsumed = false
        isTransitive = false
    }

dependencies {
    contractsBundle(variantOf(libs.platformContracts.bundle) { artifactType("zip") })
}

/** The contracts this service generates from or validates against: its own and the shared error envelope. */
val stagedServices = listOf("access", "service-runtime")
val stagedRepo = layout.buildDirectory.dir("contracts-repo")
val bundleVersion = libs.versions.platformContractsBundle

// gst.contract-server resolves its source while Gradle builds the task graph, so the layout must exist before any
// task runs: it is staged while this project is configured, once per bundle version (the marker file).
fun stageContracts() {
    val version = bundleVersion.get()
    val root = stagedRepo.get().asFile
    val marker = File(root, ".bundle-version")
    if (marker.isFile && marker.readText() == version) return
    root.deleteRecursively()
    val unpacked = File(root, ".bundle")
    project.copy {
        from(project.zipTree(contractsBundle.singleFile))
        into(unpacked)
    }
    stagedServices.forEach { svc -> stageService(unpacked, File(root, "platform-contracts/$svc"), svc, version) }
    marker.writeText(version)
}

fun stageService(
    unpacked: File,
    moduleDir: File,
    svc: String,
    version: String,
) {
    val svcDir = File(unpacked, svc)
    check(svcDir.isDirectory) { "the platform-contracts bundle $version has no $svc/ directory" }
    val versionDir = File(moduleDir, version)
    svcDir.copyRecursively(versionDir, overwrite = true)
    svcDir.walkTopDown().filter { it.isFile }.forEach { file ->
        val rel = file.relativeTo(svcDir).invariantSeparatorsPath
        val classifier = rel.substringBeforeLast('.', rel).replace('/', '-')
        val ext = rel.substringAfterLast('.', "")
        file.copyTo(File(versionDir, "$svc-$version-$classifier.$ext"), overwrite = true)
    }
    // An OpenAPI document's `../service-runtime/...` $ref resolves beside the artefact.
    if (svc != "service-runtime") {
        File(unpacked, "service-runtime").copyRecursively(File(moduleDir, "service-runtime"), overwrite = true)
    }
    File(moduleDir, "maven-metadata.xml").writeText(
        """
        <?xml version="1.0" encoding="UTF-8"?>
        <metadata>
          <groupId>platform-contracts</groupId>
          <artifactId>$svc</artifactId>
          <versioning>
            <latest>$version</latest>
            <release>$version</release>
            <versions><version>$version</version></versions>
          </versioning>
        </metadata>
        """.trimIndent(),
    )
    File(versionDir, "$svc-$version.pom").writeText(
        """
        <?xml version="1.0" encoding="UTF-8"?>
        <project xmlns="http://maven.apache.org/POM/4.0.0">
          <modelVersion>4.0.0</modelVersion>
          <groupId>platform-contracts</groupId>
          <artifactId>$svc</artifactId>
          <version>$version</version>
          <packaging>pom</packaging>
        </project>
        """.trimIndent(),
    )
}

stageContracts()

contractServer { generatorSource("platform-contracts:access:openapi.yaml") }

dependencies {
    implementation(platform(libs.springBoot.dependencies))
    implementation(libs.springBoot.starterWeb)
    implementation(libs.springBoot.starterValidation)
    implementation(libs.jackson.moduleKotlin)
    implementation(libs.swaggerAnnotations)
}

// The contract documents ship as resources (gst/contracts/access/...): the service builds its event catalogue from the
// asyncapi document, and the gates and the payload tests read the same files the code was generated from.
val contractResources = layout.buildDirectory.dir("contract-resources")
val stageContractResources =
    tasks.register<Sync>("stageContractResources") {
        from(stagedRepo.map { it.dir(".bundle/access") }) {
            include("openapi.yaml", "asyncapi.yaml", "schemas/**")
            into("gst/contracts/access")
        }
        from(stagedRepo.map { it.dir(".bundle/service-runtime/schemas") }) {
            include("error-envelope.schema.json", "cloud-event-envelope.schema.json")
            into("gst/contracts/service-runtime/schemas")
        }
        into(contractResources)
    }
sourceSets.main { resources.srcDir(contractResources) }
tasks.named("processResources") { dependsOn(stageContractResources) }
